SELECT fhir_Patient.Id, fhir_Patient.Active, fhir_Patient.GivenName, fhir_Patient.FamilyName, fhir_Patient.BirthDate, fhir_Patient.Gender, fhir_Patient.Phone, fhir_Patient.Email, fhir_Patient.AddressLine, fhir_Patient.City, fhir_Patient.State, fhir_Patient.PostalCode, fhir_Patient.Country, fhir_Patient.LastUpdated, fhir_Patient.VersionId FROM fhir_Patient WHERE (@active IS NULL OR fhir_Patient.Active = @active) AND (@familyName IS NULL OR fhir_Patient.FamilyName LIKE '%' || @familyName || '%') AND (@givenName IS NULL OR fhir_Patient.GivenName LIKE '%' || @givenName || '%') AND (@gender IS NULL OR fhir_Patient.Gender = @gender) ORDER BY fhir_Patient.FamilyName , fhir_Patient.GivenName 